        score += (6.0 - post_res) * 18.0;
    } else if post_residual < 15 {
        score += post_res * 0.45;
    }

    // 2. Predictive Lookahead: Non-linear chain-fitting anticipation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for leaving enough space for the next item
            score -= (next_item_size as f64) * 8.5;
            let next_post_res = (post_residual - next_item_size) as f64;
            // Penalize micro-fragmentation caused by the lookahead fit
            if next_post_res > 0.0 && next_post_res < 5.0 {
                score += 35.0;
            } else {
                score += next_post_res * 0.85;
            }
        } else {
            // Penalize blocking the next item
            score += (next_item_size as f64) * 7.5;
        }
    }

    // 3. Adaptive Entropy Control: Align with global mean to maintain bin uniformity.
    let density_deviation = (post_res - mean_residual).abs();
    score += density_deviation * 2.1;

    // 4. New Bin Candidate Logic: Aggressive gate-keeping.
    if bin_residual == bin_capacity {
        // Base penalty grows with open bin count and progress to force compaction
        let base_penalty = 150.0 + (open_bins_count as f64 * 1.1) + (progress * 65.0);
        score = base_penalty;

        // Only open new bins if forced or if existing bins are highly inefficient
        if fitting_bins_count == 0 {
            score = -600.0; // Absolute priority
        } else if progress > 0.75 {
            score += 200.0; // Late-stage aversion to new bins
        }
    } else {
        // 5. Consolidation Bias: Dynamic preference for fullness.
        let fullness = (capacity - bin_residual as f64) / capacity;
        score -= fullness * (55.0 * (1.0 - progress));

        // Fragmentation penalty: punish high open_bins_count relative to items processed.
        let frag_factor = (open_bins_count as f64).powf(1.15) / (step_index as f64 + 5.0).sqrt();
        score += frag_factor * 12.0;
    }

    score
}

