        if fitting_bins_count == 0 {
            score = -5.0;
        }
    } else {
        // 5. Consolidation Bias
        // Dynamic weight: prefer filling high-residual bins early, low-residual bins late
        let fullness = (capacity - bin_residual as f64) / capacity;
        score -= fullness * (12.0 * (1.0 - progress));

        // Heuristic proxy for bin utility: discourage creating too many "nearly empty" bins
        let utilization_factor = (open_bins_count as f64 / (step_index as f64 + 2.0)).sqrt();
        score += utilization_factor * 8.0;

        // Final correction: bias against very small residuals that aren't zero (the "sliver" trap)
        if post_residual > 0 && post_residual < 4 {
